module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

reg [7:0] mul_a_reg, mul_b_reg;
reg [15:0] sum;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_en_out <= 1'b0;
        mul_out <= 16'b0;
    end else begin
        if (mul_en_in) begin
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
            mul_en_out <= mul_en_in;
            sum <= 16'b0;
            for (integer i = 0; i < 8; i = i + 1) begin
                if (mul_b_reg[i]) begin
                    sum = sum + {8'b0, mul_a_reg};
                end
                mul_a_reg = {8'b0, mul_a_reg[7:1]};
            end
            mul_out <= sum;
        end
    end
end

endmodule
